// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" usar;
"src/models/product.hudhud" usar;
"src/models/order.hudhud" usar;

// Servisleri içe aktar
"src/services/auth.hudhud" usar;
"src/services/payment.hudhud" usar;
"src/services/notification.hudhud" usar;

// Yardımcı claseları içe aktar
"src/utils/validation.hudhud" usar;
"src/utils/formatting.hudhud" usar;

imprimir("============================================================");
imprimir("E-Ticaret Sistemi - Modüler Mimari Demo");
imprimir("============================================================\n");

// Servis örnekleri oluştur
var authService = nuevo AuthService();
var paymentService = nuevo PaymentService();
var notificationService = nuevo NotificationService();

imprimir("1️⃣  KULLANICI KAYDI");
imprimir("─────────────────────────────────────────────────────────\n");

// Yeni usarıcı oluştur
var newUser = nuevo User("Davut Süleyman", "davut@example.com", "güvenli123");
imprimir("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email verdaderola
si (Validation.email(newUser.email)) {
    imprimir("✓ Email geçerli: " + newUser.email);
} sino {
    imprimir("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
var authResult = authService.register(newUser);
si (authResult.success) {
    imprimir("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

imprimir("\n2️⃣  ÜRÜN OLUŞTURMA");
imprimir("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
var product = nuevo Product("MacBook Pro M3", 45000, 10, "Elektronik");
imprimir("Ürün oluşturuldu: " + product.bilgi());

// Fiyat verdaderola
si (Validation.price(product.price)) {
    imprimir("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
si (product.inStock()) {
    imprimir("✓ Ürün stokta mevcut");
} sino {
    imprimir("✗ Ürün stokta yok");
}

imprimir("\n3️⃣  SİPARİŞ OLUŞTURMA");
imprimir("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
var order = nuevo Order(
    newUser.id,
    product.id,
    1,
    product.price
);
imprimir("Sipariş oluşturuldu: " + order.bilgi());

imprimir("\n4️⃣  ÖDEME İŞLEMİ");
imprimir("─────────────────────────────────────────────────────────\n");

// Ödeme işle
var paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

si (paymentResult.success) {
    imprimir("✓ " + paymentResult.message);
    imprimir("  İşlem No: " + paymentResult.transactionId);
    imprimir("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    imprimir("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    imprimir("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} sino {
    imprimir("✗ Ödeme başarısız: " + paymentResult.error);
}

imprimir("\n============================================================");
imprimir("✓ E-Ticaret sistemi demo tamamlandı!");
imprimir("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
imprimir("============================================================");

