// Formatting Utilities - Formatlama Fonksiyonları

clase Formatting {
    estático función currency(amount, currency) {
        si (currency == "TRY") {
            retornar amount + " ₺";
        } sino {
            si (currency == "USD") {
                retornar "$" + amount;
            } sino {
                si (currency == "EUR") {
                    retornar "€" + amount;
                } sino {
                    retornar amount + " " + currency;
                }
            }
        }
    }

    estático función date(date) {
        retornar date;
    }

    estático función phone(phone) {
        // (555) 123-4567 formatı
        retornar "(" + phone + ")";
    }

    estático función number(num) {
        // 1,234,567 formatı
        retornar num;
    }
}

