clase User {
    constructor(name, email, password) {
        propio.id = Math.floor(Math.random() * 10000);
        propio.name = name;
        propio.email = email;
        propio.password = password;
        propio.createdAt = "2024-03-07";
    }

    función bilgi() {
        retornar "User #" + propio.id + ": " + propio.name + " (" + propio.email + ")";
    }

    función getId() {
        retornar propio.id;
    }
}

