// Product Model - Ürün Modeli

clase Product {
    constructor(name, price, stock, category) {
        propio.id = Math.floor(Math.random() * 10000);
        propio.name = name;
        propio.price = price;
        propio.stock = stock;
        propio.category = category;
    }

    función bilgi() {
        retornar propio.name + " - " + propio.price + " TL (Stok: " + propio.stock + ", Kategori: " + propio.category + ")";
    }

    función inStock() {
        retornar propio.stock > 0;
    }

    función getId() {
        retornar propio.id;
    }
}

