// Order Model - Sipariş Modeli

clase Order {
    constructor(userId, productId, quantity, totalPrice) {
        propio.id = Math.floor(Math.random() * 10000);
        propio.userId = userId;
        propio.productId = productId;
        propio.quantity = quantity;
        propio.totalPrice = totalPrice;
        propio.status = "pending";
        propio.createdAt = "2024-03-07";
    }

    función bilgi() {
        retornar "Sipariş #" + propio.id + " - Kullanıcı: " + propio.userId + ", Ürün: " + propio.productId + ", Adet: " + propio.quantity + ", Toplam: " + propio.totalPrice + " TL, Durum: " + propio.status;
    }

    función confirm() {
        propio.status = "confirmed";
    }

    función getId() {
        retornar propio.id;
    }
}

